const listPlanningTurns = `-- name: ListPlanningTurns :many
SELECT id, planning_session_id, sequence, reply_to_turn_id, role, kind, text, structured_payload_json, intelligence_run_id, request_key, request_fingerprint, created_at FROM planning_turns WHERE planning_session_id = ? ORDER BY sequence
`

func (q *Queries) ListPlanningTurns(ctx context.Context, planningSessionID string) ([]PlanningTurn, error) {
	rows, err := q.db.QueryContext(ctx, listPlanningTurns, planningSessionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PlanningTurn{}
	for rows.Next() {
		var i PlanningTurn
		if err := rows.Scan(
			&i.ID,
			&i.PlanningSessionID,
			&i.Sequence,
			&i.ReplyToTurnID,
			&i.Role,
			&i.Kind,
			&i.Text,
			&i.StructuredPayloadJson,
			&i.IntelligenceRunID,
			&i.RequestKey,
			&i.RequestFingerprint,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

